// SPDX-License-Identifier: UNLICENSED
pragma solidity ^0.8.0;
import {Test} from "forge-std/Test.sol";
import {ModifierEntrancy} from "../src/ModifierEntrancy.sol";

contract InvMutTest is Test {
    ModifierEntrancy c;
    function setUp() public { c = new ModifierEntrancy(); }

    function testFuzz_property(address bankDeployer) public {
        vm.assume(bankDeployer != address(0));

        vm.prank(bankDeployer);
        BankHelper helper = new BankHelper();

        address caller = address(uint160(uint256(keccak256(abi.encodePacked(bankDeployer, block.number, "caller")))));
        vm.assume(caller != address(0));

        vm.prank(address(helper));

        helper.callAirDrop(address(c));

        uint finalBalance = c.tokenBalance(address(helper));

        assertTrue(finalBalance == 20);
    }
}

contract BankHelper {
    function supportsToken() external pure returns (bytes32) {
        return keccak256(abi.encodePacked("Nu Token"));
    }
    function callAirDrop(address cAddr) external {
        ModifierEntrancy(cAddr).airDrop();
    }
}
